import sys

import h5py
import numpy as np


def decode(value):
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="replace")
    if isinstance(value, np.bytes_):
        return bytes(value).decode("utf-8", errors="replace")
    return str(value)


def strings(obj):
    if isinstance(obj, h5py.Group):
        keys = set(obj.keys())
        if {"categories", "codes"}.issubset(keys):
            categories = strings(obj["categories"])
            codes = np.asarray(obj["codes"][...], dtype=np.int64)
            return [categories[code] if code >= 0 else "" for code in codes]
        if "values" in keys:
            return strings(obj["values"])
        raise TypeError("unsupported string group: " + ",".join(sorted(keys)))
    return [decode(value) for value in obj[...]]


